// Variable declaration scopes
var globalLegacy = "I am legacy var";
let score = 100;
const MAX_SCORE = 500;

score = 150; // Valid
// MAX_SCORE = 600; // TypeError: Assignment to constant variable

if (true) {
 let blockScoped = "Hidden outside";
 var functionScoped = "Leaked outside block";
}

console.log(functionScoped);
// console.log(blockScoped); // ReferenceError

// Data Types & Coercion
let strNum = "42";
let actualNum = 42;

console.log(strNum == actualNum); // true (Loose comparison, coerced)
console.log(strNum === actualNum); // false (Strict comparison, different types)

console.log(typeof null); // "object" (Historical JS bug)
console.log(typeof undefined); // "undefined"
console.log(Number("100px")); // NaN

// Short-circuiting and Modern Operators
let user = { name: "Alex", settings: { theme: null } };

// Logical OR uses fallback on falsy values ('', 0, false, null, undefined)
let currentTheme = user.settings.theme || "Dark-Mode";

// Nullish Coalescing fallback only on null or undefined
let score = 0;
let finalScore = score ?? 100;

// Optional Chaining
let userCity = user.address?.city;

console.log(`Theme: ${currentTheme}, Score: ${finalScore}, City: ${userCity}`);

let userRole = "editor";

switch (userRole) {
 case "admin":
 console.log("Full access granted");
 break;
 case "editor":
 case "author":
 console.log("Content edit access granted");
 break;
 default:
 console.log("Read-only access granted");
}

// Ternary Operator
let statusMessage = userRole === "admin" ? "Superuser" : "Standard User";
console.log(statusMessage);

// Function Declaration (Hoisted)
function multiply(a, b = 2) {
 return a * b;
}

// Arrow Function (Implicit Return)
const double = n => n * 2;

// Arrow Function binding lexical 'this'
const timer = {
 seconds: 0,
 start() {
 setInterval(() => {
 this.seconds++;
 }, 1000);
 }
};

console.log(multiply(5));
console.log(double(10));

